def total(basket):
    counts = [0] * 5
    for book in basket:
        counts[book - 1] += 1
    counts.sort(reverse=True)

    @lru_cache(maxsize=None)
    def dp(state):
        if state == (0, 0, 0, 0, 0):
            return 0
        best = float("inf")
        available = [i for i in range(5) if state[i] > 0]
        # Try every non-empty subset of available titles as one group.
        for mask in range(1, 1 << len(available)):
            new = list(state)
            for j in range(len(available)):
                if mask >> j & 1:
                    new[available[j]] -= 1
            new.sort(reverse=True)
            size = bin(mask).count("1")
            cost = _GROUP_PRICES[size] + dp(tuple(new))
            if cost < best:
                best = cost
        return best

    return dp(tuple(counts))


